document.addEventListener('DOMContentLoaded', () => {
    const sidebar = document.getElementById('appSidebar');
    if (!sidebar) return;

    const navLinks = sidebar.querySelectorAll('[data-panel]');

    function setActiveNavLink(panelName) {
        navLinks.forEach(link => {
            const isTarget = link.getAttribute('data-panel') === panelName;
            const iconSpan = link.querySelector('.material-symbols-outlined');
            if (isTarget) {
                link.className = "nav-link flex items-center gap-md px-sm py-2 bg-secondary-container text-on-secondary-container rounded-lg font-bold transition-transform scale-[0.98]";
                if (iconSpan) iconSpan.classList.add('filled-icon');
            } else {
                link.className = "nav-link flex items-center gap-md px-sm py-2 text-on-surface-variant hover:bg-surface-container transition-all rounded-lg";
                if (iconSpan) iconSpan.classList.remove('filled-icon');
            }
        });
    }

    function switchPanel(panelName, updateHash = true) {
        const panels = document.querySelectorAll('.main-content-panel');
        if (panels.length > 0) {
            let targetPanel = document.getElementById(`panel-${panelName}`);
            if (!targetPanel) {
                targetPanel = document.getElementById('panel-dashboard');
                panelName = 'dashboard';
            }
            if (targetPanel) {
                panels.forEach(p => p.classList.add('hidden'));
                targetPanel.classList.remove('hidden');
                setActiveNavLink(panelName);
                if (updateHash) {
                    history.pushState(null, '', `#${panelName}`);
                }
            }
        } else {
            setActiveNavLink(panelName);
        }
    }

    navLinks.forEach(link => {
        link.addEventListener('click', (e) => {
            const panelName = link.getAttribute('data-panel');
            const targetPanel = document.getElementById(`panel-${panelName}`);

            if (targetPanel) {
                e.preventDefault();
                switchPanel(panelName, true);
            }
        });
    });

    // Handle logout click to open index.html (localhost:3000 root page)
    const logoutElements = document.querySelectorAll('a[href="login.html"], a[onclick*="logout"], .logout-btn');
    logoutElements.forEach(el => {
        el.addEventListener('click', (e) => {
            e.preventDefault();
            window.logoutUser(e);
        });
    });

    // Check URL hash on page load
    const hash = window.location.hash.replace('#', '');
    if (hash && document.getElementById(`panel-${hash}`)) {
        switchPanel(hash, false);
    } else {
        const currentPath = window.location.pathname.toLowerCase();
        if (currentPath.includes('prescription')) {
            setActiveNavLink('prescription');
        } else if (currentPath.includes('appointment')) {
            setActiveNavLink('appointments');
        } else if (currentPath.includes('find-vets')) {
            setActiveNavLink('vets');
        } else {
            const activeLink = sidebar.querySelector('.bg-secondary-container[data-panel]');
            if (activeLink) {
                setActiveNavLink(activeLink.getAttribute('data-panel'));
            } else {
                setActiveNavLink('dashboard');
            }
        }
    }

    window.addEventListener('popstate', () => {
        const currentHash = window.location.hash.replace('#', '') || 'dashboard';
        if (document.getElementById(`panel-${currentHash}`)) {
            switchPanel(currentHash, false);
        }
    });
});

// Global Logout function that redirects to index.html (http://localhost:3000/)
window.logoutUser = function(e) {
    if (e && e.preventDefault) e.preventDefault();
    localStorage.removeItem('userToken');
    localStorage.removeItem('currentUser');
    window.location.href = 'index.html';
};

