    const fileInput = document.getElementById('petImageFileInput');
    const dropzone = document.getElementById('petImageDropzone');
    const previewBox = document.getElementById('petImagePreviewBox');
    const previewImg = document.getElementById('petImagePreviewImg');
    const previewFileName = document.getElementById('petImageFileName');
    const removeBtn = document.getElementById('removePetImageBtn');

    const imgModeFileBtn = document.getElementById('imgModeFileBtn');
    const imgModeUrlBtn = document.getElementById('imgModeUrlBtn');
    const imgFileSection = document.getElementById('imgFileSection');
    const imgUrlSection = document.getElementById('imgUrlSection');
    const petImageUrlInput = document.getElementById('petImageUrlInput');

    // Image Mode Toggle
    if (imgModeFileBtn && imgModeUrlBtn) {
        imgModeFileBtn.addEventListener('click', () => {
            imgFileSection.classList.remove('hidden');
            imgUrlSection.classList.add('hidden');
            imgModeFileBtn.className = 'px-2.5 py-0.5 rounded-md bg-primary text-white font-bold transition-all shadow-sm';
            imgModeUrlBtn.className = 'px-2.5 py-0.5 rounded-md bg-surface-variant text-on-surface-variant hover:bg-surface-container transition-all';
        });
        imgModeUrlBtn.addEventListener('click', () => {
            imgFileSection.classList.add('hidden');
            imgUrlSection.classList.remove('hidden');
            imgModeUrlBtn.className = 'px-2.5 py-0.5 rounded-md bg-primary text-white font-bold transition-all shadow-sm';
            imgModeFileBtn.className = 'px-2.5 py-0.5 rounded-md bg-surface-variant text-on-surface-variant hover:bg-surface-container transition-all';
        });
    }

    // File selection and Drag & Drop
    if (dropzone && fileInput) {
        dropzone.addEventListener('click', () => fileInput.click());

        dropzone.addEventListener('dragover', (e) => {
            e.preventDefault();
            dropzone.classList.add('border-primary', 'bg-primary/10');
        });
        dropzone.addEventListener('dragleave', () => {
            dropzone.classList.remove('border-primary', 'bg-primary/10');
        });
        dropzone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropzone.classList.remove('border-primary', 'bg-primary/10');
            if (e.dataTransfer.files && e.dataTransfer.files[0]) {
                handleFile(e.dataTransfer.files[0]);
            }
        });

        fileInput.addEventListener('change', (e) => {
            if (e.target.files && e.target.files[0]) {
                handleFile(e.target.files[0]);
            }
        });
    }

    function handleFile(file) {
        if (!file.type.startsWith('image/')) {
            alert('Please select a valid image file (PNG, JPG, WEBP, etc.)');
            return;
        }
        const reader = new FileReader();
        reader.onload = (event) => {
            selectedPetFileBase64 = event.target.result;
            if (previewImg) previewImg.src = selectedPetFileBase64;
            if (previewFileName) previewFileName.textContent = file.name;
            if (previewBox) previewBox.classList.remove('hidden');
            if (dropzone) dropzone.classList.add('hidden');
        };
        reader.readAsDataURL(file);
    }

    if (removeBtn) {
        removeBtn.addEventListener('click', () => {
            selectedPetFileBase64 = null;
            if (fileInput) fileInput.value = '';
            if (previewImg) previewImg.src = '';
            if (previewBox) previewBox.classList.add('hidden');
            if (dropzone) dropzone.classList.remove('hidden');
        });
    }

    // Handle Add Pet Form Submit with ImageKit CDN URL Conversion
    if (addPetForm) {
        addPetForm.addEventListener('submit', async (e) => {
            e.preventDefault();

            const submitBtn = document.getElementById('savePetSubmitBtn');
            const originalBtnHtml = submitBtn ? submitBtn.innerHTML : 'Save Pet';

            if (submitBtn) {
                submitBtn.disabled = true;
                submitBtn.innerHTML = '<span class="material-symbols-outlined animate-spin text-sm">sync</span> Uploading to ImageKit CDN...';
            }

            const formData = new FormData(addPetForm);
