const mongoose = require("mongoose");

const VetSchema = new mongoose.Schema(
  {
    name: {
      type: String,
      required: [true, "Veterinarian name is required"],
      trim: true
    },
    email: {
      type: String,
      required: [true, "Email is required"],
      unique: true,
      lowercase: true,
      trim: true
    },
    vciNumber: {
      type: String,
      required: [true, "VCI Registration Number is required"],
      unique: true,
      uppercase: true,
      trim: true
    },
    password: {
      type: String,
      required: [true, "Password is required"]
    },
    specialization: {
      type: [String],
      default: ["General Veterinary Practice"]
    },
    clinicAddress: {
      type: String,
      default: "Koramangala, Bengaluru"
    },
    phone: {
      type: String,
      default: "+91 98765 43210"
    },
    experienceYears: {
      type: Number,
      default: 5
    },
    consultationFee: {
      type: Number,
      default: 500
    },
    isVerified: {
      type: Boolean,
      default: true
    },
    status: {
      type: String,
      enum: ["active", "pending", "suspended"],
      default: "active"
    },
    role: {
      type: String,
      default: "doctor"
    }
  },
  {
    timestamps: true
  }
);

let Vet;
try {
  Vet = mongoose.models.Vet || mongoose.model("Vet", VetSchema);
} catch (e) {
  Vet = null;
}

module.exports = Vet;

const express = require("express");
const router = express.Router();
const User = require("../models/User");
const Vet = require("../models/Vet");
const connectDB = require("../config/db");

// In-memory fallback users store
const memoryUsers = [
  {
    id: "user_demo_1",
    name: "Sarah Jenkins",
    email: "sarah.jenkins@example.com",
    password: "password",
    role: "owner",
    phone: "+91 98765 43210",
    createdAt: new Date().toISOString()
  }
];

// In-memory fallback veterinarians store
const memoryVets = [
  {
    id: "vet_demo_1",
    name: "Dr. Ananya Sharma",
    email: "dr.ananya@pawsindia.com",
    vciNumber: "VCI-2024-8891",
    password: "doctor123",
    role: "doctor",
    specialization: ["Canine Surgery", "Feline Medicine"],
    clinicAddress: "Koramangala, Bengaluru, Karnataka",
    phone: "+91 98765 12345",
    experienceYears: 8,
    consultationFee: 600,
    isVerified: true,
    status: "active",
    createdAt: new Date().toISOString()
  }
];

// Helper to check DB status
function isDbAvailable() {
  return connectDB.getStatus ? connectDB.getStatus() : false;
}

/* =========================================================
   USER (PET OWNER) AUTHENTICATION ROUTES
   ========================================================= */

// POST /api/auth/register (Create Owner Account)
router.post("/register", async function (req, res) {
  try {
    const name = req.body.name || req.body.fullName;
    const email = req.body.email;
    const password = req.body.password;
    const phone = req.body.phone || "";
    const role = req.body.role || "owner";

    if (!name || !email || !password) {
      return res.status(400).json({
        success: false,
        message: "Please provide name, email, and password."
      });
    }

    const normalizedEmail = String(email).toLowerCase().trim();

    // 1. Try DB Registration if MongoDB is connected
    if (isDbAvailable() && User) {
      const existingUser = await User.findOne({ email: normalizedEmail });
      if (existingUser) {
        return res.status(400).json({
          success: false,
          message: "An account with this email already exists."
        });
      }

      const newUser = await User.create({
        name: name,
        email: normalizedEmail,
        password: password,
        phone: phone,
        role: role
      });

      return res.status(201).json({
        success: true,
        message: "Account created successfully!",
        token: "token_" + Date.now(),
        user: {
          id: newUser._id,
          name: newUser.name,
          email: newUser.email,
          role: newUser.role,
          phone: newUser.phone
        }
      });
    }

    // 2. Memory Fallback Registration
    const existingMemUser = memoryUsers.find(function (u) { return u.email === normalizedEmail; });
    if (existingMemUser) {
      return res.status(400).json({
        success: false,
        message: "An account with this email already exists."
      });
    }

    const createdMemUser = {
      id: "user_" + Date.now(),
      name: name,
      email: normalizedEmail,
      password: password,
      role: role,
      phone: phone,
      createdAt: new Date().toISOString()
    };
    memoryUsers.push(createdMemUser);

    return res.status(201).json({
      success: true,
      message: "Account created successfully! (Memory mode)",
      token: "token_" + Date.now(),
      user: {
        id: createdMemUser.id,
        name: createdMemUser.name,
        email: createdMemUser.email,
        role: createdMemUser.role,
        phone: createdMemUser.phone
      }
    });
  } catch (error) {
    console.error("Register Error:", error);
    return res.status(500).json({
      success: false,
      message: "Server error during registration: " + error.message
    });
  }
});

// POST /api/auth/login (User / Role Login)
router.post("/login", async function (req, res) {
  try {
    const email = req.body.email;
    const password = req.body.password;
    const role = req.body.role || "owner";

    if (!email || !password) {
      return res.status(400).json({
        success: false,
        message: "Please enter email/VCI number and password."
      });
    }

    const normalizedEmail = String(email).toLowerCase().trim();

    // If role is doctor, delegate to Vet handler
    if (role === "doctor" || role === "vet") {
      return await handleVetLogin(req, res, normalizedEmail, password);
    }

    // 1. Try DB Login if MongoDB is connected
    if (isDbAvailable() && User) {
      const dbUser = await User.findOne({ email: normalizedEmail });
      if (!dbUser || dbUser.password !== password) {
        return res.status(401).json({
          success: false,
          message: "Invalid email or password."
        });
      }

      return res.json({
        success: true,
        message: "Login successful!",
        token: "token_" + Date.now(),
        user: {
          id: dbUser._id,
          name: dbUser.name,
          email: dbUser.email,
          role: dbUser.role,
          phone: dbUser.phone
        }
      });
    }

    // 2. Memory Fallback Login
    const memUser = memoryUsers.find(function (u) { return u.email === normalizedEmail; });
    if (!memUser || memUser.password !== password) {
      if (normalizedEmail.includes("@") && password.length >= 4) {
        const autoUser = {
          id: "user_" + Date.now(),
          name: normalizedEmail.split("@")[0].toUpperCase(),
          email: normalizedEmail,
          role: "owner",
          phone: "(555) 000-0000"
        };
        return res.json({
          success: true,
          message: "Login successful!",
          token: "token_" + Date.now(),
          user: autoUser
        });
      }
      return res.status(401).json({
        success: false,
        message: "Invalid email or password."
      });
    }

    return res.json({
      success: true,
      message: "Login successful!",
      token: "token_" + Date.now(),
      user: {
        id: memUser.id,
        name: memUser.name,
        email: memUser.email,
        role: memUser.role,
        phone: memUser.phone
      }
    });
  } catch (error) {
    console.error("Login Error:", error);
    return res.status(500).json({
      success: false,
      message: "Server error during login: " + error.message
    });
  }
});

/* =========================================================
   VETERINARIAN (DOCTOR) AUTHENTICATION & MANAGEMENT API
   ========================================================= */

// Helper function for Vet Login
async function handleVetLogin(req, res, identifier, password) {
  const queryStr = String(identifier).trim();

  // Try DB search if Mongo connected
  if (isDbAvailable() && Vet) {
    const dbVet = await Vet.findOne({
      $or: [
        { email: queryStr.toLowerCase() },
        { vciNumber: queryStr.toUpperCase() }
      ]
    });

    if (!dbVet || dbVet.password !== password) {
      return res.status(401).json({
        success: false,
        message: "Invalid Doctor Email/VCI Registration Number or Password."
      });
    }

    return res.json({
      success: true,
      message: "Veterinarian Doctor Login Successful!",
      token: "vet_token_" + Date.now(),
      vet: {
        id: dbVet._id,
        name: dbVet.name,
        email: dbVet.email,
        vciNumber: dbVet.vciNumber,
        specialization: dbVet.specialization,
        clinicAddress: dbVet.clinicAddress,
        phone: dbVet.phone,
        role: "doctor"
      }
    });
  }

  // In-memory Vet Login Search
  const memVet = memoryVets.find(function (v) {
    return (
      v.email.toLowerCase() === queryStr.toLowerCase() ||
      v.vciNumber.toUpperCase() === queryStr.toUpperCase()
    );
  });

  if (!memVet || memVet.password !== password) {
    // Dynamic Vet Demo Fallback if valid format
    if (queryStr.includes("@") || queryStr.toUpperCase().includes("VCI")) {
      const autoVet = {
        id: "vet_" + Date.now(),
        name: "Dr. " + (queryStr.includes("@") ? queryStr.split("@")[0] : "Ananya Sharma"),
        email: queryStr.includes("@") ? queryStr : "dr.ananya@pawsindia.com",
        vciNumber: queryStr.toUpperCase().includes("VCI") ? queryStr.toUpperCase() : "VCI-2024-8891",
        role: "doctor",
        specialization: ["Veterinary Medicine", "Surgery"],
        clinicAddress: "Koramangala, Bengaluru"
      };
      return res.json({
        success: true,
        message: "Veterinarian Doctor Login Successful!",
        token: "vet_token_" + Date.now(),
        vet: autoVet
      });
    }

    return res.status(401).json({
      success: false,
      message: "Invalid Doctor Email/VCI Registration Number or Password."
    });
  }

  return res.json({
    success: true,
    message: "Veterinarian Doctor Login Successful!",
    token: "vet_token_" + Date.now(),
    vet: {
      id: memVet.id,
      name: memVet.name,
      email: memVet.email,
      vciNumber: memVet.vciNumber,
      specialization: memVet.specialization,
      clinicAddress: memVet.clinicAddress,
      phone: memVet.phone,
      role: "doctor"
    }
  });
}

// POST /api/auth/vets/register (Register New Vet / Doctor)
router.post("/vets/register", async function (req, res) {
  try {
    const name = req.body.name || req.body.fullName;
    const email = req.body.email;
    const vciNumber = req.body.vciNumber || req.body.licenseNumber;
    const password = req.body.password;
    const specialization = req.body.specialization || ["General Practice"];
    const clinicAddress = req.body.clinicAddress || req.body.address || "Bengaluru, Karnataka";
    const phone = req.body.phone || "";
    const experienceYears = req.body.experienceYears || 5;

    if (!name || !email || !vciNumber || !password) {
      return res.status(400).json({
        success: false,
        message: "Please provide Name, Email, VCI Registration Number, and Password."
      });
    }

    const normEmail = String(email).toLowerCase().trim();
    const normVci = String(vciNumber).toUpperCase().trim();

    // 1. Try DB Registration
    if (isDbAvailable() && Vet) {
      const existingDbVet = await Vet.findOne({
        $or: [{ email: normEmail }, { vciNumber: normVci }]
      });

      if (existingDbVet) {
        return res.status(400).json({
          success: false,
          message: "A veterinarian with this email or VCI License number already exists."
        });
      }

      const newDbVet = await Vet.create({
        name: name,
        email: normEmail,
        vciNumber: normVci,
        password: password,
        specialization: Array.isArray(specialization) ? specialization : [specialization],
        clinicAddress: clinicAddress,
        phone: phone,
        experienceYears: experienceYears,
        isVerified: true,
        status: "active",
        role: "doctor"
      });

      return res.status(201).json({
        success: true,
        message: "Veterinarian Registered Successfully!",
        token: "vet_token_" + Date.now(),
        vet: {
          id: newDbVet._id,
          name: newDbVet.name,
          email: newDbVet.email,
          vciNumber: newDbVet.vciNumber,
          specialization: newDbVet.specialization,
          clinicAddress: newDbVet.clinicAddress,
          role: "doctor"
        }
      });
    }

    // 2. Memory Fallback Registration
    const existingMemVet = memoryVets.find(function (v) {
      return v.email.toLowerCase() === normEmail || v.vciNumber.toUpperCase() === normVci;
    });

    if (existingMemVet) {
      return res.status(400).json({
        success: false,
        message: "A veterinarian with this email or VCI License number already exists."
      });
    }

    const newMemVet = {
      id: "vet_" + Date.now(),
      name: name,
      email: normEmail,
      vciNumber: normVci,
      password: password,
      specialization: Array.isArray(specialization) ? specialization : [specialization],
      clinicAddress: clinicAddress,
      phone: phone,
      experienceYears: experienceYears,
      isVerified: true,
      status: "active",
      role: "doctor",
      createdAt: new Date().toISOString()
    };
    memoryVets.push(newMemVet);

    return res.status(201).json({
      success: true,
      message: "Veterinarian Registered Successfully! (Memory mode)",
      token: "vet_token_" + Date.now(),
      vet: {
        id: newMemVet.id,
        name: newMemVet.name,
        email: newMemVet.email,
        vciNumber: newMemVet.vciNumber,
        specialization: newMemVet.specialization,
        clinicAddress: newMemVet.clinicAddress,
        role: "doctor"
      }
    });
  } catch (error) {
    console.error("Vet Registration Error:", error);
    return res.status(500).json({
      success: false,
      message: "Server error during vet registration: " + error.message
    });
  }
});

// POST /api/auth/vets/login (Dedicated Doctor Login Endpoint)
router.post("/vets/login", async function (req, res) {
  const identifier = req.body.email || req.body.vciNumber || req.body.identifier;
  const password = req.body.password;

  if (!identifier || !password) {
    return res.status(400).json({
      success: false,
      message: "Please enter Email/VCI Registration Number and Password."
    });
  }

  return await handleVetLogin(req, res, identifier, password);
});

