const express = require("express");
const cors = require("cors");
const dotenv = require("dotenv");

const connectDB = require("./config/db");
const apiRoutes = require("./routes/apiRoutes");
const authRoutes = require("./routes/authRoutes");
const petRoutes = require("./routes/petRoutes");
const imagekitRoutes = require("./routes/imagekitRoutes");

dotenv.config();

const app = express();

// Middleware
app.use(cors());
app.use(express.json({ limit: "10mb" }));
app.use(express.urlencoded({ extended: true, limit: "10mb" }));

// Request logging middleware
app.use(function (req, res, next) {
  console.log("[" + new Date().toISOString() + "] " + req.method + " " + req.url);
  next();
});

// Database Connection
connectDB();

// Register API Routes
app.use("/api/auth", authRoutes);
app.use("/api/pets", petRoutes);
app.use("/api/imagekit", imagekitRoutes);
app.use("/api", apiRoutes);

// Root Index Route
app.get("/", function (req, res) {
  res.json({
    success: true,
    message: "Welcome to Gemini Backend API Server",
    endpoints: {
      health: "/api/health",
      status: "/api/status",
      login: "/api/auth/login",
      register: "/api/auth/register",
      vetLogin: "/api/auth/vets/login",
      vetRegister: "/api/auth/vets/register",
      pets: "/api/pets",
      imagekitAuth: "/api/imagekit/auth",
      imagekitUpload: "/api/imagekit/upload",
      items: "/api/items"
    }
  });
});

// 404 Route Handler
app.use(function (req, res) {
  res.status(404).json({
    success: false,
    message: "Endpoint not found: " + req.originalUrl
  });
});

// Start Server
const PORT = process.env.PORT || 5000;

const server = app.listen(PORT, function () {
  console.log("==========================================");
  console.log("  Gemini API Server Running Successfully  ");
  console.log("  Port: " + PORT);
  console.log("  Health URL: http://localhost:" + PORT + "/api/health");
  console.log("  Auth Login: http://localhost:" + PORT + "/api/auth/login");
  console.log("  Auth Register: http://localhost:" + PORT + "/api/auth/register");
  console.log("  Vet Auth Login: http://localhost:" + PORT + "/api/auth/vets/login");
  console.log("  Vet Auth Register: http://localhost:" + PORT + "/api/auth/vets/register");
  console.log("  Pets API: http://localhost:" + PORT + "/api/pets");
  console.log("==========================================");
});

// Keep process active
setInterval(function () {}, 1000000);

module.exports = app;

