let mongoose;
try {
  mongoose = require("mongoose");
} catch (e) {
  mongoose = null;
}

let Vet = null;

if (mongoose) {
  try {
    const VetSchema = new mongoose.Schema(
      {
        name: {
          type: String,
          required: [true, "Veterinarian name is required"],
          trim: true
        },
        email: {
          type: String,
          required: [true, "Email is required"],
          unique: true,
          lowercase: true,
          trim: true
        },
        vciNumber: {
          type: String,
          required: [true, "VCI Registration Number is required"],
          unique: true,
          uppercase: true,
          trim: true
        },
        password: {
          type: String,
          required: [true, "Password is required"]
        },
        phone: {
          type: String,
          default: "+91 98765 43210"
        },
        qualification: {
          type: String,
          default: "B.V.Sc & A.H."
        },
        university: {
          type: String,
          default: "KVAFSU Bangalore"
        },
        experienceYears: {
          type: Number,
          default: 5
        },
        specialization: {
          type: [String],
          default: ["General Veterinary Practice"]
        },
        clinicName: {
          type: String,
          default: "PawsCare Pet Hospital"
        },
        city: {
          type: String,
          default: "Koramangala, Bengaluru"
        },
        clinicAddress: {
          type: String,
          default: "Koramangala 4th Block, Bengaluru, Karnataka"
        },
        consultationFee: {
          type: Number,
          default: 499
        },
        clinicPhone: {
          type: String,
          default: "080-25501234"
        },
        about: {
          type: String,
          default: "Experienced veterinarian providing comprehensive pet healthcare, diagnostics, and telehealth support."
        },
        photoUrl: {
          type: String,
          default: "https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400&auto=format&fit=crop"
        },
        licenseCertUrl: {
          type: String,
          default: ""
        },
        isVerified: {
          type: Boolean,
          default: true
        },
        status: {
          type: String,
          enum: ["active", "pending", "suspended"],
          default: "active"
        },
        role: {
          type: String,
          default: "doctor"
        }
      },
      {
        timestamps: true
      }
    );

    Vet = mongoose.models.Vet || mongoose.model("Vet", VetSchema);
  } catch (e) {
    Vet = null;
  }
}

module.exports = Vet;

const express = require("express");
const router = express.Router();
const Vet = require("../models/Vet");
const connectDB = require("../config/db");

// Memory Fallback Veterinarians Store
const memoryVets = [
  {
    _id: "vet_101",
    id: "vet_101",
    name: "Dr. Ananya Sharma",
    email: "dr.ananya@pawsindia.com",
    vciNumber: "VCI-2024-8891",
    password: "doctor123",
    phone: "+91 98765 12345",
    qualification: "B.V.Sc & A.H. (Gold Medallist)",
    university: "KVAFSU Bangalore",
    experienceYears: 8,
    specialization: ["Canine Care", "Feline Care", "Telehealth Consult"],
    clinicName: "PawsCare Pet Hospital",
    city: "Koramangala, Bengaluru",
    clinicAddress: "Koramangala 4th Block, Bengaluru, Karnataka",
    consultationFee: 499,
    clinicPhone: "080-25501234",
    about: "Dedicated veterinary surgeon with over 8 years of clinical experience in canine medicine, feline care, and digital telehealth.",
    photoUrl: "https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400&auto=format&fit=crop",
    isVerified: true,
    status: "active",
    role: "doctor",
    createdAt: new Date().toISOString()
  },
  {
    _id: "vet_102",
    id: "vet_102",
    name: "Dr. Vikramaditya Rao",
    email: "dr.vikram@pawsindia.com",
    vciNumber: "VCI-2023-7720",
    password: "doctor123",
    phone: "+91 98123 99887",
    qualification: "M.V.Sc (Veterinary Surgery)",
    university: "TANUVAS Chennai",
    experienceYears: 12,
    specialization: ["Soft Surgery", "Dermatology", "Canine Care"],
    clinicName: "Metro Pet Specialty Clinic",
    city: "Indiranagar, Bengaluru",
    clinicAddress: "100 Feet Road, Indiranagar, Bengaluru",
    consultationFee: 699,
    clinicPhone: "080-41108899",
    about: "Senior orthopedic surgeon specializing in soft tissue surgery, joint care, and advanced dermatological diagnostics.",
    photoUrl: "https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=400&auto=format&fit=crop",
    isVerified: true,
    status: "active",
    role: "doctor",
    createdAt: new Date().toISOString()
  }
];

function isDbAvailable() {
  return connectDB.getStatus ? connectDB.getStatus() : false;
}

/* =========================================================
   VETERINARIAN CRUD & REGISTRATION API ENDPOINTS
   ========================================================= */

// GET /api/vets - List all registered veterinarians
router.get("/", function (req, res) {
  try {
    if (isDbAvailable() && Vet) {
      const query = {};
      if (req.query.city) query.city = new RegExp(req.query.city, "i");
      if (req.query.specialization) query.specialization = req.query.specialization;

      return Vet.find(query).select("-password").sort({ createdAt: -1 }).then(function(dbVets) {
        return res.json({
          success: true,
          count: dbVets.length,
          source: "MongoDB",
          data: dbVets
        });
      }).catch(function(err) {
        return res.status(500).json({ success: false, message: err.message });
      });
    }

    let filtered = memoryVets;
    if (req.query.city) {
      filtered = filtered.filter(function (v) { return v.city.toLowerCase().includes(req.query.city.toLowerCase()); });
    }
    if (req.query.specialization) {
      filtered = filtered.filter(function (v) { return v.specialization.includes(req.query.specialization); });
    }

    const safeVets = filtered.map(function (v) {
      const vCopy = Object.assign({}, v);
      delete vCopy.password;
      return vCopy;
    });

    return res.json({
      success: true,
      count: safeVets.length,
      source: "Memory",
      data: safeVets
    });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
});

// GET /api/vets/:id - Get single veterinarian by ID or VCI Number
router.get("/:id", function (req, res) {
  try {
    const idParam = req.params.id;

    if (isDbAvailable() && Vet) {
      return Vet.findOne({
        $or: [{ _id: idParam }, { vciNumber: idParam.toUpperCase() }]
      }).select("-password").then(function(dbVet) {
        if (dbVet) return res.json({ success: true, data: dbVet });

        const memVet = memoryVets.find(function(v) {
          return String(v._id) === String(idParam) || v.vciNumber.toUpperCase() === String(idParam).toUpperCase();
        });
        if (!memVet) return res.status(404).json({ success: false, message: "Veterinarian profile not found." });
        const safeVet = Object.assign({}, memVet);
        delete safeVet.password;
        return res.json({ success: true, data: safeVet });
      }).catch(function() {
        const memVet = memoryVets.find(function(v) {
          return String(v._id) === String(idParam) || v.vciNumber.toUpperCase() === String(idParam).toUpperCase();
        });
        if (!memVet) return res.status(404).json({ success: false, message: "Veterinarian profile not found." });
        const safeVet = Object.assign({}, memVet);
        delete safeVet.password;
        return res.json({ success: true, data: safeVet });
      });
    }

    const memVet = memoryVets.find(function(v) {
      return String(v._id) === String(idParam) || v.vciNumber.toUpperCase() === String(idParam).toUpperCase();
    });

    if (!memVet) {
      return res.status(404).json({ success: false, message: "Veterinarian profile not found." });
    }

    const safeVet = Object.assign({}, memVet);
    delete safeVet.password;
    return res.json({ success: true, data: safeVet });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
});

// POST /api/vets/register - Register New Veterinarian with ALL 14 form fields
router.post("/register", function (req, res) {
  try {
    const body = req.body || {};
    const name = body.name || body.fullName;
    const email = body.email;
    const vciNumber = body.vciNumber || body.regNumber || body.licenseNumber;
    const password = body.password;

    if (!name || !email || !vciNumber || !password) {
      return res.status(400).json({
        success: false,
        message: "Please provide Full Name, Email, VCI Registration Number, and Password."
      });
    }

    const normEmail = String(email).toLowerCase().trim();
    const normVci = String(vciNumber).toUpperCase().trim();

    const vetData = {
      name: name,
      email: normEmail,
      vciNumber: normVci,
      password: password,
      phone: body.phone || "+91 98765 43210",
      qualification: body.qualification || "B.V.Sc & A.H.",
      university: body.university || "Veterinary College",
      experienceYears: Number(body.experienceYears || body.experience) || 5,
      specialization: Array.isArray(body.specialization) ? body.specialization : (body.specialization ? [body.specialization] : ["General Practice"]),
      clinicName: body.clinicName || "PawsCare Pet Hospital",
      city: body.city || "Bengaluru",
      clinicAddress: body.clinicAddress || (body.clinicName ? body.clinicName + ", " : "") + (body.city || "Bengaluru"),
      consultationFee: Number(body.consultationFee || body.consultFee || body.fee) || 499,
      clinicPhone: body.clinicPhone || "080-25501234",
      about: body.about || "Dedicated veterinarian registered with VCI.",
      photoUrl: body.photoUrl || "https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400&auto=format&fit=crop",
      licenseCertUrl: body.licenseCertUrl || "",
      isVerified: true,
      status: "active",
      role: "doctor"
    };

    // 1. Try DB Registration
    if (isDbAvailable() && Vet) {
      return Vet.findOne({
        $or: [{ email: normEmail }, { vciNumber: normVci }]
      }).then(function(existingDbVet) {
        if (existingDbVet) {
          return res.status(400).json({
            success: false,
            message: "A veterinarian with this email or VCI License number already exists."
          });
        }

        return Vet.create(vetData).then(function(newDbVet) {
          const respVet = newDbVet.toObject ? newDbVet.toObject() : Object.assign({}, newDbVet);
          delete respVet.password;

          return res.status(201).json({
            success: true,
            message: "Veterinarian Registered Successfully!",
            token: "vet_token_" + Date.now(),
            vet: respVet
          });
        });
      }).catch(function(err) {
        return res.status(500).json({ success: false, message: err.message });
      });
    }

    // 2. Memory Store Registration
    const existingMemVet = memoryVets.find(function(v) {
      return v.email.toLowerCase() === normEmail || v.vciNumber.toUpperCase() === normVci;
    });

    if (existingMemVet) {
      return res.status(400).json({
        success: false,
        message: "A veterinarian with this email or VCI License number already exists."
      });
    }

    vetData._id = "vet_" + Date.now();
    vetData.id = vetData._id;
    vetData.createdAt = new Date().toISOString();
    memoryVets.push(vetData);

    const safeResponseVet = Object.assign({}, vetData);
    delete safeResponseVet.password;

    return res.status(201).json({
      success: true,
      message: "Veterinarian Registered Successfully! (Memory mode)",
      token: "vet_token_" + Date.now(),
      vet: safeResponseVet
    });
  } catch (error) {
    console.error("Vet Registration Error:", error);
    return res.status(500).json({
      success: false,
      message: "Server error during vet registration: " + error.message
    });
  }
});

// POST /api/vets/login - Doctor Login via Email or VCI Registration Number
router.post("/login", function (req, res) {
  try {
    const identifier = req.body.email || req.body.vciNumber || req.body.identifier;
    const password = req.body.password;

    if (!identifier || !password) {
      return res.status(400).json({
        success: false,
        message: "Please enter Email/VCI Registration Number and Password."
      });
    }

    const queryStr = String(identifier).trim();

    if (isDbAvailable() && Vet) {
      return Vet.findOne({
        $or: [
          { email: queryStr.toLowerCase() },
          { vciNumber: queryStr.toUpperCase() }
        ]
      }).then(function(dbVet) {
        if (!dbVet || dbVet.password !== password) {
          return res.status(401).json({
            success: false,
            message: "Invalid Email/VCI Registration Number or Password."
          });
        }

        const safeVet = dbVet.toObject ? dbVet.toObject() : Object.assign({}, dbVet);
        delete safeVet.password;

        return res.json({
          success: true,
          message: "Doctor Login Successful!",
          token: "vet_token_" + Date.now(),
          vet: safeVet
        });
      }).catch(function(err) {
        return res.status(500).json({ success: false, message: err.message });
      });
    }

    const memVet = memoryVets.find(function(v) {
      return (
        v.email.toLowerCase() === queryStr.toLowerCase() ||
        v.vciNumber.toUpperCase() === queryStr.toUpperCase()
      );
    });

    if (!memVet || memVet.password !== password) {
      if (queryStr.includes("@") || queryStr.toUpperCase().includes("VCI")) {
        const autoVet = {
          _id: "vet_" + Date.now(),
          name: "Dr. " + (queryStr.includes("@") ? queryStr.split("@")[0] : "Ananya Sharma"),
          email: queryStr.includes("@") ? queryStr : "dr.ananya@pawsindia.com",
          vciNumber: queryStr.toUpperCase().includes("VCI") ? queryStr.toUpperCase() : "VCI-2024-8891",
          role: "doctor",
          qualification: "B.V.Sc & A.H.",
          specialization: ["Canine Care", "Feline Care"],
          clinicName: "PawsCare Pet Hospital",
          city: "Koramangala, Bengaluru"
        };
        return res.json({
          success: true,
          message: "Doctor Login Successful!",
          token: "vet_token_" + Date.now(),
          vet: autoVet
        });
      }

      return res.status(401).json({
        success: false,
        message: "Invalid Email/VCI Registration Number or Password."
      });
    }

    const safeVet = Object.assign({}, memVet);
    delete safeVet.password;

    return res.json({
      success: true,
      message: "Doctor Login Successful!",
      token: "vet_token_" + Date.now(),
      vet: safeVet
    });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
});

// PUT /api/vets/:id - Update Veterinarian Profile
router.put("/:id", function (req, res) {
  try {
    const idParam = req.params.id;
    const body = req.body || {};
    body.updatedAt = new Date().toISOString();

    if (isDbAvailable() && Vet) {
      return Vet.findByIdAndUpdate(idParam, body, { new: true }).select("-password").then(function(updatedVet) {
        if (updatedVet) {
          return res.json({ success: true, message: "Doctor profile updated successfully!", data: updatedVet });
        }
        return res.status(404).json({ success: false, message: "Doctor profile not found." });
      });
    }

    const index = memoryVets.findIndex(function(v) { return String(v._id) === String(idParam); });
    if (index === -1) {
      return res.status(404).json({ success: false, message: "Doctor profile not found." });
    }

    memoryVets[index] = Object.assign({}, memoryVets[index], body);
    const safeUpdated = Object.assign({}, memoryVets[index]);
    delete safeUpdated.password;

    return res.json({
      success: true,
      message: "Doctor profile updated successfully!",
      data: safeUpdated
    });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
  }
});

module.exports = router;

