          vet: autoVet
        });
      }

      return res.status(401).json({
        success: false,
        message: "Invalid Email/VCI Registration Number or Password."
      });
    }

    const safeVet = Object.assign({}, memVet);
    delete safeVet.password;

    return res.json({
      success: true,
      message: "Doctor Login Successful!",
      token: "vet_token_" + Date.now(),
