    const index = memoryVets.findIndex(function(v) { return String(v._id) === String(idParam); });
    if (index === -1) {
      return res.status(404).json({ success: false, message: "Doctor profile not found." });
    }

    memoryVets[index] = Object.assign({}, memoryVets[index], body);
    const safeUpdated = Object.assign({}, memoryVets[index]);
    delete safeUpdated.password;

    return res.json({
      success: true,
      message: "Doctor profile updated successfully!",
      data: safeUpdated
    });
  } catch (error) {
    return res.status(500).json({ success: false, message: error.message });
