const express = require("express");
const router = express.Router();
const Vet = require("../models/Vet");
const connectDB = require("../config/db");

// Initial Seed Dataset for 'vets' collection
const initialSeedVets = [
  {
    name: "Dr. Ananya Sharma",
    email: "dr.ananya@pawsindia.com",
    vciNumber: "VCI-2024-8891",
    password: "doctor123",
    phone: "+91 98765 12345",
    qualification: "B.V.Sc & A.H. (Gold Medallist)",
    university: "KVAFSU Bangalore",
    experienceYears: 8,
    specialization: ["Canine Care", "Feline Care", "Telehealth Consult", "Soft Surgery"],
    clinicName: "PawsCare Pet Hospital",
    city: "Koramangala, Bengaluru",
    clinicAddress: "Koramangala 4th Block, Bengaluru, Karnataka",
    consultationFee: 499,
    clinicPhone: "080-25501234",
    about: "Dedicated veterinary surgeon with over 8 years of clinical experience in canine medicine, feline care, and digital telehealth consultations.",
    photoUrl: "https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=500&auto=format&fit=crop",
    licenseCertUrl: "",
    isVerified: true,
    status: "active",
    role: "doctor"
  }
];

// Fallback memory collection store
let memoryVetsCollection = initialSeedVets.map(function(v, index) {
  return Object.assign({}, v, { _id: "vet_10" + (index + 1), id: "vet_10" + (index + 1), createdAt: new Date().toISOString() });
});

// In-Memory Data Isolation Store keyed by vetId / vciNumber
const doctorDataStore = {
  "vet_101": {
    appointments: [
      { id: "apt_1", petName: "Sheru", petType: "Dog (Indie)", ownerName: "Rajesh Kumar", ownerPhone: "+91 98765 11223", date: "Today", time: "10:00 AM", status: "Upcoming", type: "Telehealth", fee: 499 },
      { id: "apt_2", petName: "Luna", petType: "Dog (Golden Retriever)", ownerName: "Priya Sharma", ownerPhone: "+91 98111 22334", date: "Today", time: "02:30 PM", status: "Confirmed", type: "In-Clinic", fee: 499 },
      { id: "apt_3", petName: "Milo", petType: "Cat (Persian)", ownerName: "Amit Patel", ownerPhone: "+91 97222 33445", date: "Tomorrow", time: "11:30 AM", status: "Pending", type: "Telehealth", fee: 499 }
    ],
    availability: {
      weeklyHours: { "Monday": "09:00 AM - 05:00 PM", "Tuesday": "09:00 AM - 05:00 PM", "Wednesday": "09:00 AM - 05:00 PM", "Thursday": "09:00 AM - 05:00 PM", "Friday": "09:00 AM - 05:00 PM", "Saturday": "10:00 AM - 02:00 PM", "Sunday": "Closed" },
      slotDuration: 30,
      emergencyConsult: true
    },
    earnings: {
      thisMonth: 42500,
      totalConsultations: 85,
      pendingPayout: 12499,
      history: [
        { date: "01 Sep 2026", description: "Weekly Settlement (18 Consults)", amount: 8982, status: "Transferred" },
        { date: "25 Aug 2026", description: "Weekly Settlement (22 Consults)", amount: 10978, status: "Transferred" }
      ]
    }
  }
};

function isDbAvailable() {
  return connectDB.getStatus ? connectDB.getStatus() : false;
}

function ensureVetsCollectionSeeded() {
  if (isDbAvailable() && Vet) {
    return Vet.countDocuments().then(function(count) {
      if (count === 0) {
        return Vet.insertMany(initialSeedVets).then(function() {
          console.log("Stored 1 initial record into 'vets' database collection.");
        });
      }
    }).catch(function(e) {
      console.warn("Vets collection seed notice:", e.message);
    });
  }
  return Promise.resolve();
}

function getScopedDoctorStore(vetId) {
  const key = String(vetId);
  if (!doctorDataStore[key]) {
    doctorDataStore[key] = {
      appointments: [],
      availability: {
        weeklyHours: { "Monday": "10:00 AM - 04:00 PM", "Tuesday": "10:00 AM - 04:00 PM", "Wednesday": "10:00 AM - 04:00 PM", "Thursday": "10:00 AM - 04:00 PM", "Friday": "10:00 AM - 04:00 PM", "Saturday": "Closed", "Sunday": "Closed" },
        slotDuration: 30,
        emergencyConsult: false
      },
      earnings: {
        thisMonth: 0,
        totalConsultations: 0,
        pendingPayout: 0,
        history: []
      }
    };
  }
  return doctorDataStore[key];
}

/* =========================================================
   VETERINARIAN DATABASE COLLECTION API ENDPOINTS ('vets')
   ========================================================= */

// GET /api/vets - List all public veterinarian profiles
router.get("/", function (req, res) {
  try {
    if (isDbAvailable() && Vet) {
      return ensureVetsCollectionSeeded().then(function() {
        const query = {};
        if (req.query.city) query.city = new RegExp(req.query.city, "i");
        if (req.query.specialization) query.specialization = req.query.specialization;

        return Vet.find(query).select("-password").sort({ createdAt: -1 }).then(function(dbVets) {
          return res.json({
            success: true,
            count: dbVets.length,
            collection: "vets",
            data: dbVets
          });
        });
