// Global Role-Based Authentication & Protected Route Guard Module
window.VetAuth = {
  // Enforce Protected Routes & Role-Based Layout Redirects
  protectDoctorRoute: function() {
    const rawUser = localStorage.getItem('currentUser');
    const token = localStorage.getItem('userToken');
    const currentPath = window.location.pathname.toLowerCase();

    const isDoctorPage = currentPath.includes('doctor-dashboard') ||
                         currentPath.includes('vet-appointments') ||
                         currentPath.includes('vet-availability') ||
                         currentPath.includes('create-prescription') ||
                         currentPath.includes('vet-earnings');

    const isOwnerPage = currentPath.includes('owner-dashboard') ||
                        currentPath.includes('my-pets') ||
                        currentPath.includes('my_pets');

    let user = null;
    if (rawUser) {
      try { user = JSON.parse(rawUser); } catch(e) { user = null; }
    }

    const isDoctorRole = user && (user.role === 'doctor' || user.role === 'vet' || Boolean(user.vciNumber) || (user.email && user.email.includes('dr.')));

    // 1. If accessing Doctor Portal Page
    if (isDoctorPage) {
      if (!token || !user) {
        console.warn("Unauthenticated access attempt to Doctor Portal. Redirecting to vet-login.html...");
        window.location.href = 'vet-login.html';
        return null;
      }
      if (!isDoctorRole) {
        console.warn("Pet Owner attempting to access Doctor Portal. Redirecting to owner-dashboard.html...");
        window.location.href = 'owner-dashboard.html';
        return null;
      }
      return user;
    }

    // 2. If accessing Owner Portal Page as a Doctor
    if (isOwnerPage) {
      if (!token || !user) {
        console.warn("Unauthenticated access attempt to Owner Dashboard. Redirecting to login.html...");
        window.location.href = 'login.html';
        return null;
      }
      if (isDoctorRole) {
        console.warn("Doctor accessing Pet Owner Dashboard. Redirecting to doctor-dashboard.html...");
        window.location.href = 'doctor-dashboard.html';
        return null;
      }
      return user;
    }

    return user;
  },

  // Get current authenticated doctor's unique ID/VCI
  getDoctorId: function(user) {
    if (!user) {
      const rawUser = localStorage.getItem('currentUser');
      if (rawUser) {
        try { user = JSON.parse(rawUser); } catch(e) {}
      }
    }
    return (user && (user._id || user.id || user.vciNumber)) ? (user._id || user.id || user.vciNumber) : 'vet_101';
  },

  // Populate doctor info in sidebar and page headers
  populateDoctorHeader: function(user) {
    if (!user) return;

    // Header / Welcome Name
    const welcomeHeader = document.getElementById('welcomeHeader');
    if (welcomeHeader) {
      welcomeHeader.textContent = `Good morning, ${user.name || 'Doctor'} 👋`;
    }

    // Sidebar Doctor Name & VCI
    const sidebarName = document.getElementById('doctorSidebarName');
    if (sidebarName) {
      sidebarName.textContent = user.name || 'Dr. Ananya Sharma';
    }

    const sidebarVci = document.getElementById('doctorSidebarVci');
    if (sidebarVci) {
      sidebarVci.textContent = user.vciNumber ? `VCI: ${user.vciNumber}` : 'VCI Verified Specialist';
    }

    const sidebarAvatar = document.getElementById('doctorSidebarAvatar') || document.getElementById('doctorAvatarImg');
    if (sidebarAvatar && user.photoUrl) {
      sidebarAvatar.src = user.photoUrl;
    }
  }
};

// Global Role-Based Profile Navigation Handler
window.navigateToRoleProfile = function(e) {
  if (e && e.preventDefault) e.preventDefault();
  const rawUser = localStorage.getItem('currentUser');
  const token = localStorage.getItem('userToken');

  if (!token || !rawUser) {
    window.location.href = 'login.html';
    return;
  }

  try {
    const user = JSON.parse(rawUser);
    const isDoctor = user.role === 'doctor' || user.role === 'vet' || Boolean(user.vciNumber) || (user.email && user.email.includes('dr.'));
    if (isDoctor) {
      window.location.href = 'doctor-dashboard.html';
    } else {
      window.location.href = 'owner-dashboard.html';
    }
  } catch(err) {
    window.location.href = 'login.html';
  }
};

