// Global Strict Role-Based Authentication, Protected Routes & Navigation Guard Module
(function() {
  window.VetAuth = {
    // 1. Strict Role-Based Protected Routes & Automatic Redirect Guard
    protectRoutes: function() {
      const rawUser = localStorage.getItem('currentUser');
      const token = localStorage.getItem('userToken');
      const currentPath = window.location.pathname.toLowerCase();

      let user = null;
      if (rawUser) {
        try { user = JSON.parse(rawUser); } catch(e) { user = null; }
      }

      const isDoctorRole = user && (user.role === 'doctor' || user.role === 'vet' || Boolean(user.vciNumber) || (user.email && user.email.includes('dr.')));
      const isOwnerRole = user && !isDoctorRole;

      // Category A: Doctor-Only Protected Pages
      const isDoctorPage = currentPath.includes('doctor-dashboard') ||
                           currentPath.includes('vet-appointments') ||
                           currentPath.includes('vet-availability') ||
                           currentPath.includes('create-prescription') ||
                           currentPath.includes('vet-earnings');

      // Category B: Owner-Only Protected Pages
      const isOwnerPage = currentPath.includes('owner-dashboard') ||
                          currentPath.includes('my-pets') ||
                          currentPath.includes('my_pets');

      // Category C: Auth Pages (login, vet-login, register, vet-register)
      const isAuthPage = currentPath.includes('login.html') ||
                         currentPath.includes('vet-login') ||
                         currentPath.includes('register.html') ||
                         currentPath.includes('vet-register');

      // --- RULE 1: Doctor Page Access Enforcement ---
      if (isDoctorPage) {
        if (!token || !user) {
          console.warn("Unauthenticated access attempt to Doctor Portal. Redirecting to vet-login.html...");
          window.location.href = 'vet-login.html';
          return null;
        }
        if (!isDoctorRole) {
          console.warn("Pet Owner attempting to access Doctor Portal. Redirecting to owner-dashboard.html...");
          window.location.href = 'owner-dashboard.html';
          return null;
        }
        return user;
      }

      // --- RULE 2: Owner Page Access Enforcement ---
      if (isOwnerPage) {
        if (!token || !user) {
          console.warn("Unauthenticated access attempt to Owner Dashboard. Redirecting to login.html...");
          window.location.href = 'login.html';
          return null;
        }
        if (isDoctorRole) {
          console.warn("Doctor attempting to access Pet Owner Dashboard. Redirecting to doctor-dashboard.html...");
          window.location.href = 'doctor-dashboard.html';
          return null;
        }
        return user;
      }

      // --- RULE 3: Auth Pages Redirect if already logged in ---
      if (isAuthPage && token && user) {
        if (isDoctorRole) {
          console.log("Doctor already logged in. Redirecting to doctor-dashboard.html...");
          window.location.href = 'doctor-dashboard.html';
          return user;
        } else if (isOwnerRole) {
          console.log("Pet Owner already logged in. Redirecting to owner-dashboard.html...");
          window.location.href = 'owner-dashboard.html';
          return user;
        }
      }

      return user;
    },

    // Get current authenticated doctor's unique ID/VCI
    getDoctorId: function(user) {
      if (!user) {
        const rawUser = localStorage.getItem('currentUser');
        if (rawUser) {
          try { user = JSON.parse(rawUser); } catch(e) {}
        }
      }
      return (user && (user._id || user.id || user.vciNumber)) ? (user._id || user.id || user.vciNumber) : 'vet_101';
    },

    // Populate user info in headers across Doctor and Owner portals
    populateUserHeader: function(user) {
      if (!user) return;

      const isDoctorRole = user.role === 'doctor' || user.role === 'vet' || Boolean(user.vciNumber);

      // Header / Welcome Name
      const welcomeHeader = document.getElementById('welcomeHeader');
      if (welcomeHeader) {
        welcomeHeader.textContent = `Good morning, ${user.name || (isDoctorRole ? 'Doctor' : 'Pet Parent')} 👋`;
      }

      // Sidebar User Name
      const sidebarName = document.getElementById('doctorSidebarName') || document.getElementById('ownerSidebarName');
      if (sidebarName) {
        sidebarName.textContent = user.name || (isDoctorRole ? 'Dr. Ananya Sharma' : 'Sarah Jenkins');
      }

      // Doctor VCI
      const sidebarVci = document.getElementById('doctorSidebarVci');
      if (sidebarVci) {
        sidebarVci.textContent = user.vciNumber ? `VCI: ${user.vciNumber}` : 'VCI Verified Specialist';
      }

      // User Avatars
      const sidebarAvatar = document.getElementById('doctorSidebarAvatar') || document.getElementById('doctorAvatarImg') || document.getElementById('ownerSidebarAvatar');
      if (sidebarAvatar && user.photoUrl) {
        sidebarAvatar.src = user.photoUrl;
      }
    }
  };

  // Legacy compatibility alias
  window.VetAuth.protectDoctorRoute = window.VetAuth.protectRoutes;

  // 2. Global Role-Based Navigation Handlers
  window.navigateToRoleProfile = function(e) {
    if (e && e.preventDefault) e.preventDefault();
    const rawUser = localStorage.getItem('currentUser');
    const token = localStorage.getItem('userToken');

    if (!token || !rawUser) {
      window.location.href = 'login.html';
      return;
    }

    try {
      const user = JSON.parse(rawUser);
      const isDoctor = user.role === 'doctor' || user.role === 'vet' || Boolean(user.vciNumber) || (user.email && user.email.includes('dr.'));
      if (isDoctor) {
        window.location.href = 'doctor-dashboard.html';
      } else {
        window.location.href = 'owner-dashboard.html';
      }
    } catch(err) {
      window.location.href = 'login.html';
    }
  };

  window.navigateToRoleHome = function(e) {
    if (e && e.preventDefault) e.preventDefault();
    const rawUser = localStorage.getItem('currentUser');
    const token = localStorage.getItem('userToken');

    if (!token || !rawUser) {
      window.location.href = 'index.html';
      return;
    }

    try {
      const user = JSON.parse(rawUser);
      const isDoctor = user.role === 'doctor' || user.role === 'vet' || Boolean(user.vciNumber) || (user.email && user.email.includes('dr.'));
      if (isDoctor) {
        window.location.href = 'doctor-dashboard.html';
      } else {
        window.location.href = 'owner-dashboard.html';
      }
    } catch(err) {
      window.location.href = 'index.html';
    }
  };

  document.addEventListener('DOMContentLoaded', () => {
      // Execute Protected Route Enforcement
      const currentUser = window.VetAuth.protectRoutes();
      if (currentUser) {
          window.VetAuth.populateUserHeader(currentUser);
      }

      // Attach click listeners to Profile links across site
      const profileLinks = document.querySelectorAll('a[href="profile.html"], .profile-link-btn');
      profileLinks.forEach(link => {
        link.addEventListener('click', (e) => {
          window.navigateToRoleProfile(e);
        });
      });

      // Attach click listeners to Logo / Brand links across site
      const logoLinks = document.querySelectorAll('.brand-logo-link, a.brand-home-link');
      logoLinks.forEach(link => {
        link.addEventListener('click', (e) => {
          window.navigateToRoleHome(e);
        });
      });

      // Handle App Sidebar Panel Navigation if present
      const sidebar = document.getElementById('appSidebar');
      if (!sidebar) return;

      const navLinks = sidebar.querySelectorAll('[data-panel]');

      function setActiveNavLink(panelName) {
          navLinks.forEach(link => {
              const isTarget = link.getAttribute('data-panel') === panelName;
              const iconSpan = link.querySelector('.material-symbols-outlined');
              if (isTarget) {
                  link.className = "nav-link flex items-center gap-3 px-4 py-2.5 bg-primary text-white font-bold rounded-xl shadow-sm transition-transform scale-[0.98]";
                  if (iconSpan) iconSpan.classList.add('filled-icon');
              } else {
                  link.className = "nav-link flex items-center gap-3 px-4 py-2.5 text-on-surface-variant hover:bg-surface-container transition-all rounded-xl";
                  if (iconSpan) iconSpan.classList.remove('filled-icon');
              }
          });
      }

      function switchPanel(panelName, updateHash = true) {
          const panels = document.querySelectorAll('.main-content-panel');
          if (panels.length > 0) {
              let targetPanel = document.getElementById(`panel-${panelName}`);
              if (!targetPanel) {
                  targetPanel = document.getElementById('panel-dashboard');
                  panelName = 'dashboard';
              }
              if (targetPanel) {
                  panels.forEach(p => p.classList.add('hidden'));
                  targetPanel.classList.remove('hidden');
                  setActiveNavLink(panelName);
                  if (updateHash) {
                      history.pushState(null, '', `#${panelName}`);
                  }
              }
          } else {
              setActiveNavLink(panelName);
          }
      }

      navLinks.forEach(link => {
          link.addEventListener('click', (e) => {
              const panelName = link.getAttribute('data-panel');
              const targetPanel = document.getElementById(`panel-${panelName}`);

              if (targetPanel) {
                  e.preventDefault();
                  switchPanel(panelName, true);
              }
          });
      });

      // Check current path & hash on page load
      const hash = window.location.hash.replace('#', '');
      if (hash && document.getElementById(`panel-${hash}`)) {
          switchPanel(hash, false);
      } else {
          const currentPath = window.location.pathname.toLowerCase();
          if (currentPath.includes('doctor-dashboard')) {
              setActiveNavLink('doctor-dashboard');
          } else if (currentPath.includes('vet-appointments')) {
              setActiveNavLink('vet-appointments');
          } else if (currentPath.includes('vet-availability')) {
              setActiveNavLink('vet-availability');
          } else if (currentPath.includes('create-prescription')) {
              setActiveNavLink('create-prescription');
          } else if (currentPath.includes('vet-earnings')) {
              setActiveNavLink('vet-earnings');
          } else if (currentPath.includes('doctor-profile')) {
              setActiveNavLink('doctor-profile');
          } else if (currentPath.includes('prescription')) {
              setActiveNavLink('prescription');
          } else if (currentPath.includes('appointment')) {
              setActiveNavLink('appointments');
          } else if (currentPath.includes('find-vets')) {
              setActiveNavLink('vets');
          } else if (currentPath.includes('my-pets') || currentPath.includes('my_pets')) {
              setActiveNavLink('pets');
          } else {
              const activeLink = sidebar.querySelector('.bg-primary[data-panel]');
              if (activeLink) {
                  setActiveNavLink(activeLink.getAttribute('data-panel'));
              } else {
                  setActiveNavLink('dashboard');
              }
          }
      }
  });

  // Global Logout function
  window.logoutUser = function(e) {
      if (e && e.preventDefault) e.preventDefault();
      localStorage.removeItem('userToken');
      localStorage.removeItem('currentUser');
      window.location.href = 'index.html';
  };
})();

